// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(100, "Token", "TKN"); }
    function testRegression_property() public {
        c.burn(10);
        c.freezeAccount(address(this), true);
        address other = address(1);
        bool success;
        try c.transfer(other, 1) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success == false);
    }
}
